CREATE TABLE IF NOT EXISTS research_sources(source_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,url TEXT NOT NULL,title TEXT NOT NULL,quality TEXT NOT NULL,published_at TEXT,retrieved_at TEXT NOT NULL,content_hash TEXT NOT NULL);CREATE TABLE IF NOT EXISTS research_claims(claim_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,claim_text TEXT NOT NULL,source_ids_json TEXT NOT NULL,confidence REAL NOT NULL,current_fact INTEGER NOT NULL,verified_at TEXT NOT NULL);